  let dbl = false;
  for (let i = v.length - 1; i >= 0; i--) {
    let d = Number(v[i]);
    if (dbl) {
      d *= 2;
      if (d > 9) d -= 9;
    }
    sum += d;
    dbl = !dbl;
  }
