export function focusFirstError(ids: string[], errors: Record<string, string>): void {
  // `ids` is in the design's own field order, so "first" means the field the
  // user meets first, not Map or Object.keys enumeration order.
  const first = ids.find((id) => errors[id]);
  if (first === undefined) return;
  const entry = fieldRegistry.get(first);
  if (!entry) return;
  const { node, scroll } = entry;
  // A screen with no ScrollView cannot scroll — but the field is then whole on
  // screen anyway, so focusing it is still the right thing to do.
  const focusIt = (): void => {
    if (typeof node.focus === 'function') node.focus();
  };
  const container = scroll.view;
  if (!container || typeof container.scrollTo !== 'function') {
    focusIt();
    return;
  }
  const scrollToY = (y: number): void => {
    container.scrollTo!({ y: Math.max(0, y - SCROLL_MARGIN), animated: true });
    focusIt();
  };

  // Preferred: measure the field against the scroller's INNER (content) view.
  // That yields a content coordinate directly, which is what scrollTo takes —
  // no dependency on the tracked offset, so it stays correct even if a scroll
  // event was missed.
  //
  // The ancestor must be the inner view's HOST INSTANCE (getInnerViewRef).
  // getInnerViewNode returns a numeric node handle, which the classic renderer
  // accepted — but Fabric's measureLayout rejects anything that is not a host
  // instance with the dev error "ref.measureLayout must be called with a ref
  // to a native component" and, crucially, returns WITHOUT invoking either
  // callback. Preferring the node handle therefore turned every blocked-submit
  // scroll on the new architecture into that error toast and nothing else.
  // The handle is kept only as a classic-renderer fallback, and the whole call
  // is fenced: a bad ancestor must degrade to the viewport arithmetic, never
  // leave the press looking dead (or worse, throw out of the press handler).
  const innerRef = container.getInnerViewRef?.();
  const fabric = (globalThis as { nativeFabricUIManager?: unknown }).nativeFabricUIManager != null;
  const inner =
    // stated as steps rather than a nested ternary (S3358): prefer the host
    // instance, and fall back to the numeric handle only off Fabric, which
    // rejects it
    (() => {
      if (innerRef !== null && typeof innerRef === 'object') return innerRef;
      return fabric ? null : container.getInnerViewNode?.();
    })();
  if (inner !== null && inner !== undefined && typeof node.measureLayout === 'function') {
    try {
      node.measureLayout(
        inner,
        (_x, y) => scrollToY(y),
        // Measuring against a node that is not an ancestor throws rather than
        // returning: fall through to the viewport arithmetic instead of leaving
        // the press looking dead.
        () => measureFromWindow(container, node, scroll, scrollToY, focusIt),
      );
    } catch {
      measureFromWindow(container, node, scroll, scrollToY, focusIt);
    }
    return;
  }
  measureFromWindow(container, node, scroll, scrollToY, focusIt);
}

/**
 * Fallback for engines whose ScrollView exposes no inner node (react-native-web
 * among them): both boxes report viewport coordinates, and the scroller's own
 * offset converts the delta back into a content coordinate.
 */
function measureFromWindow(
  container: NonNullable<ScrollHandle['view']>,
  node: FieldNode,
  scroll: ScrollHandle,
  scrollToY: (y: number) => void,
  focusIt: () => void,
): void {
  if (
    typeof container.measureInWindow !== 'function' ||
    typeof node.measureInWindow !== 'function'
  ) {
    focusIt();
    return;
  }
  container.measureInWindow((_cx, cy) => {
    node.measureInWindow!((_fx, fy) => scrollToY(scroll.offset + (fy - cy)));
  });
}
